// src/lib/db.ts
import "dotenv/config";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import Prisma from "@prisma/client";
var { PrismaClient } = Prisma;
var globalForPrisma = globalThis;
